import { PASSWORD, USERS, expect, test } from "../../fixtures";

function sessionSetCookies(headers: { name: string; value: string }[]): string[] {
  return headers
    .filter((h) => h.name.toLowerCase() === "set-cookie")
    .flatMap((h) => h.value.split("\n"))
    .map((v) => v.trim())
    .filter((v) => /^session=/i.test(v));
}

test.describe("Sign in", () => {
  test(
    "signing out clears the session cookie",
    { tag: "@AUTH-06" },
    async ({ request }) => {
      // Arrange: sign in as the seeded member, which stores the session cookie in this context
      const login = await request.post("/api/auth/login", {
        data: { email: USERS.member, password: PASSWORD },
      });
      expect(login.status()).toBe(200);
      const loginCookies = sessionSetCookies(login.headersArray());
      expect(loginCookies.length, "login sets a session cookie").toBeGreaterThan(0);

      const before = await request.storageState();
      const sessionBefore = before.cookies.find((c) => c.name === "session");
      expect(sessionBefore?.value, "session cookie present before sign out").toBeTruthy();

      // Act
      const response = await request.post("/api/auth/logout");

      // Assert
      expect(response.status()).toBe(204);

      const cleared = sessionSetCookies(response.headersArray());
      expect(cleared.length, "logout sends a Set-Cookie for session").toBeGreaterThan(0);
      const header = cleared[cleared.length - 1];

      // The cookie value is emptied
      const value = header.slice("session=".length).split(";")[0].trim();
      expect(["", '""']).toContain(value);

      // And it is expired immediately (Max-Age=0 or an Expires date in the past)
      const lower = header.toLowerCase();
      const maxAge = /max-age=(-?\d+)/.exec(lower);
      const expires = /expires=([^;]+)/i.exec(header);
      const expiredByMaxAge = maxAge !== null && Number(maxAge[1]) <= 0;
      const expiredByDate =
        expires !== null && new Date(expires[1].trim()).getTime() <= Date.now();
      expect(
        expiredByMaxAge || expiredByDate,
        `session cookie is expired by logout: ${header}`,
      ).toBe(true);

      // The client no longer holds a usable session cookie
      const after = await request.storageState();
      const sessionAfter = after.cookies.find((c) => c.name === "session");
      expect(sessionAfter?.value ?? "").toMatch(/^(""|)$/);
    },
  );
});
